// BISNAGO → ingest tee — generated from the ADR-0045 client descriptor.
// Place on a SECOND wire off your SparkPlug-assembly node (a tee, not a redirect).
// The shim enforces the group scope (first topic segment) = "BISNAGO" and routes
// the tenant on lower("BISNAGO"). Key is read from env BISNAGO_INGEST_KEY — NEVER hardcoded.

const key = env.get("BISNAGO_INGEST_KEY");
if (!key) {
    node.error("BISNAGO_INGEST_KEY env var is not set — refusing to POST without an ingest key", msg);
    return null;
}

let envelope = msg.payload;
if (Array.isArray(envelope)) {
    envelope = { timestamp: Date.now(), gateway: "bisnago-edge", metrics: envelope };
} else if (envelope && !envelope.timestamp) {
    envelope.timestamp = Date.now();
}
if (!envelope || !Array.isArray(envelope.metrics) || envelope.metrics.length === 0) {
    node.warn("tee: payload has no metrics[]; skipping this message");
    return null;
}

msg.headers = { "Content-Type": "application/json", "X-Ingest-Key": key };
msg.payload = envelope;
return msg;
